WITH base AS (SELECT * FROM customers WHERE MONTH(signup_date) IN (3, 4, 12) AND signup_date >= '2024-06-17'), summary AS (SELECT is_active, ROUND((100 * SUM(CASE WHEN city = 'London' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_london, SORT_ARRAY(COLLECT_SET(country)) AS country_list FROM base GROUP BY is_active) SELECT * FROM summary WHERE pct_london >= 63 ORDER BY pct_london DESC;
